{
    #[Assert\NotBlank(payload: ['severity' => 'error'])]
    protected string $username;

    #[Assert\NotBlank(payload: ['severity' => 'error'])]
    protected string $password;

    #[Assert\Iban(payload: ['severity' => 'warning'])]
